062b\\\\u0644 \\\\u0627\\\\u0644\\\\u0646\\\\u064a\\\\u062a\\\\u0631\\\\u0648\\\\u062c\\\\u0644\\\\u064a\\\\u0633\\\\u0631\\\\u064a\\\\u0646\\\\u060c \\\\u0644\\\\u062a\\\\u0648\\\\u0633\\\\u064a\\\\u0639 \\\\u0627\\\\u0644\\\\u0623\\\\u0648\\\\u0639\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u062f\\\\u0645\\\\u0648\\\\u064a\\\\u0629 \\\\u0648\\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u0630\\\\u0628\\\\u062d\\\\u0629 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0631\\\\u064a\\\\u0629.\\\", \\\"**\\\\u062a\\\\u0630\\\\u0643\\\\u064a\\\\u0631:** \\\\u0647\\\\u0630\\\\u0647 \\\\u0627\\\\u0644\\\\u0645\\\\u0639\\\\u0644\\\\u0648\\\\u0645\\\\u0627\\\\u062a \\\\u0644\\\\u0644\\\\u062a\\\\u0648\\\\u0639\\\\u064a\\\\u0629 \\\\u0641\\\\u0642\\\\u0637. \\\\u0644\\\\u0627 \\\\u062a\\\\u062a\\\\u0646\\\\u0627\\\\u0648\\\\u0644 \\\\u0623\\\\u064a \\\\u062f\\\\u0648\\\\u0627\\\\u0621 \\\\u0642\\\\u0644\\\\u0628\\\\u064a \\\\u062f\\\\u0648\\\\u0646 \\\\u0648\\\\u0635\\\\u0641\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0629\\\\u060c \\\\u0648\\\\u0644\\\\u0627 \\\\u062a\\\\u063a\\\\u064a\\\\u0631 \\\\u062c\\\\u0631\\\\u0639\\\\u062a\\\\u0643 \\\\u0623\\\\u0648 \\\\u062a\\\\u062a\\\\u0648\\\\u0642\\\\u0641 \\\\u0639\\\\u0646 \\\\u0627\\\\u0644\\\\u062f\\\\u0648\\\\u0627\\\\u0621 \\\\u062f\\\\u0648\\\\u0646 \\\\u0627\\\\u0633\\\\u062a\\\\u0634\\\\u0627\\\\u0631\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0628\\\\u0643.\\\"]\"','عام','\"[\\\"\\\\u0627\\\\u0647\\\\u0645\\\", \\\"\\\\u0623\\\\u062f\\\\u0648\\\\u064a\\\\u0629\\\", \\\"\\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\"]\"',0.95,'deepseek',2,0,0,'2026-03-08 00:10:02','2026-03-08 00:43:59'),(19,'medical of haert','medical of haert','[معلومات عامة عن القلب]\n\nالقلب هو عضو عضلي يعمل كمضخة لتوزيع الدم المحمل بالأكسجين والمواد الغذائية إلى جميع أنسجة الجسم عبر الدورة الدموية. يتكون من أربع حجرات (أذينان وبطينان) ويعمل بنظام كهربائي دقيق ينظم نبضاته.\n\n[النقاط]:\n• الوظيفة الأساسية: ضخ الدم عبر الجسم.\n• المكونات الرئيسية: العضلة القلبية، الصمامات (الأبهري، التاجي، ثلاثي الشرفات، الرئوي)، والشرايين التاجية التي تغذيه.\n• الأمراض الشائعة: تشمل أمراض الشرايين التاجية، وفشل القلب، واضطرابات النظم القلبي (الخفقان).\n• العناية بالقلب: تشمل اتباع نظام غذائي صحي، ممارسة الرياضة، تجنب التدخين، وإدارة الضغوط النفسية.','إجابة طبية','\"[\\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0648\\\\u0638\\\\u064a\\\\u0641\\\\u0629 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0627\\\\u0633\\\\u064a\\\\u0629: \\\\u0636\\\\u062e \\\\u0627\\\\u0644\\\\u062f\\\\u0645 \\\\u0639\\\\u0628\\\\u0631 \\\\u0627\\\\u0644\\\\u062c\\\\u0633\\\\u0645.\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0645\\\\u0643\\\\u0648\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0631\\\\u0626\\\\u064a\\\\u0633\\\\u064a\\\\u0629: \\\\u0627\\\\u0644\\\\u0639\\\\u0636\\\\u0644\\\\u0629 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u064a\\\\u0629\\\\u060c \\\\u0627\\\\u0644\\\\u0635\\\\u0645\\\\u0627\\\\u0645\\\\u0627\\\\u062a (\\\\u0627\\\\u0644\\\\u0623\\\\u0628\\\\u0647\\\\u0631\\\\u064a\\\\u060c \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u060c \\\\u062b\\\\u0644\\\\u0627\\\\u062b\\\\u064a \\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0641\\\\u0627\\\\u062a\\\\u060c \\\\u0627\\\\u0644\\\\u0631\\\\u0626\\\\u0648\\\\u064a)\\\\u060c \\\\u0648\\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0627\\\\u064a\\\\u064a\\\\u0646 \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u062a\\\\u064a \\\\u062a\\\\u063a\\\\u0630\\\\u064a\\\\u0647.\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0623\\\\u0645\\\\u0631\\\\u0627\\\\u0636 \\\\u0627\\\\u0644\\\\u0634\\\\u0627\\\\u0626\\\\u0639\\\\u0629: \\\\u062a\\\\u0634\\\\u0645\\\\u0644 \\\\u0623\\\\u0645\\\\u0631\\\\u0627\\\\u0636 \\\\u0627\\\\u0644\\\\u0634\\\\u0631\\\\u0627\\\\u064a\\\\u064a\\\\u0646 \\\\u0627\\\\u0644\\\\u062a\\\\u0627\\\\u062c\\\\u064a\\\\u0629\\\\u060c \\\\u0648\\\\u0641\\\\u0634\\\\u0644 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u060c \\\\u0648\\\\u0627\\\\u0636\\\\u0637\\\\u0631\\\\u0627\\\\u0628\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0646\\\\u0638\\\\u0645 \\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628\\\\u064a (\\\\u0627\\\\u0644\\\\u062e\\\\u0641\\\\u0642\\\\u0627\\\\u0646).\\\", \\\"\\\\u2022 \\\\u0627\\\\u0644\\\\u0639\\\\u0646\\\\u0627\\\\u064a\\\\u0629 \\\\u0628\\\\u0627\\\\u0644\\\\u0642\\\\u0644\\\\u0628: \\\\u062a\\\\u0634\\\\u0645\\\\u0644 \\\\u0627\\\\u062a\\\\u0628\\\\u0627\\\\u0639 \\\\u0646\\\\u0638\\\\u0627\\\\u0645 \\\\u063a\\\\u0630\\\\u0627\\\\u0626\\\\u064a \\\\u0635\\\\u062d\\\\u064a\\\\u060c \\\\u0645\\\\u0645\\\\u0627\\\\u0631\\\\u0633\\\\u0629 \\\\u0627\\\\u0644\\\\u0631\\\\u064a\\\\u0627\\\\u0636\\\\u0629\\\\u060c \\\\u062a\\\\u062c\\\\u0646\\\\u0628 \\\\u0627\\\\u0644\\\\u062a\\\\u062f\\\\u062e\\\\u064a\\\\u0646\\\\u060c \\\\u0648\\\\u0625\\\\u062f\\\\u0627\\\\u0631\\\\u0629 \\\\u0627\\\\u0644\\\\u0636\\\\u063a\\\\u0648\\\\u0637 \\\\u0627\\\\u0644\\\\u0646\\\\u0641\\\\u0633\\\\u064a\\\\u0629.\\\"]\"','عام','\"[\\\"medical\\\", \\\"of\\\", \\\"haert\\\"]\"',0.95,'deepseek',1,0,0,'2026-03-24 07:26:01','2026-03-24 07:26:01'),(20,'مناخيري بتاكلنى وعيني تدمع و سنانى بتوجعنى','مناخيري بتاكلني وعيني تدمع و سناني بتوجعني','[أعراض متعددة تحتاج تقييم طبي]:\nأعاني من ألم في الأسنان مع تدميع العينين، وهذه الأعراض قد تشير إلى مشكلة تحتاج فحصاً عاجلاً. ألم الأسنان الذي يمتد إلى العين يمكن أن يكون مرتبطاً بمشكلة في عصب السن أو التهاب في الجيوب الأنفية المجاورة.\n\n• **آلام الأسنان الممتدة للعين** قد تدل على التهاب عصب أو خراج.\n• **تدميع العين** المصاحب قد يكون رد فعل عصبي للألم أو علامة على التهاب الجيوب.\n• **يجب مراجعة طبيب الأسنان فوراً** للفحص وتحديد السبب.\n• **تجنب المسكنات القوية** دون وصفة طبية.\n• **استخدم كمادات باردة** على الخد لتخفيف الألم مؤقتاً.','إجابة طبية','\"[\\\"\\\\u2022 **\\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0646\\\\u0627\\\\u0646 \\\\u0627\\\\u0644\\\\u0645\\\\u0645\\\\u062a\\\\u062f\\\\u0629 \\\\u0644\\\\u0644\\\\u0639\\\\u064a\\\\u0646** \\\\u0642\\\\u062f \\\\u062a\\\\u062f\\\\u0644 \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0639\\\\u0635\\\\u0628 \\\\u0623\\\\u0648 \\\\u062e\\\\u0631\\\\u0627\\\\u062c.\\\", \\\"\\\\u2022 **\\\\u062a\\\\u062f\\\\u0645\\\\u064a\\\\u0639 \\\\u0627\\\\u0644\\\\u0639\\\\u064a\\\\u0646** \\\\u0627\\\\u0644\\\\u0645\\\\u0635\\\\u0627\\\\u062d\\\\u0628 \\\\u0642\\\\u062f \\\\u064a\\\\u0643\\\\u0648\\\\u0646 \\\\u0631\\\\u062f \\\\u0641\\\\u0639\\\\u0644 \\\\u0639\\\\u0635\\\\u0628\\\\u064a \\\\u0644\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0623\\\\u0648 \\\\u0639\\\\u0644\\\\u0627\\\\u0645\\\\u0629 \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062a\\\\u0647\\\\u0627\\\\u0628 \\\\u0627\\\\u0644\\\\u062c\\\\u064a\\\\u0648\\\\u0628.\\\", \\\"\\\\u2022 **\\\\u064a\\\\u062c\\\\u0628 \\\\u0645\\\\u0631\\\\u0627\\\\u062c\\\\u0639\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0628 \\\\u0627\\\\u0644\\\\u0623\\\\u0633\\\\u0646\\\\u0627\\\\u0646 \\\\u0641\\\\u0648\\\\u0631\\\\u0627\\\\u064b** \\\\u0644\\\\u0644\\\\u0641\\\\u062d\\\\u0635 \\\\u0648\\\\u062a\\\\u062d\\\\u062f\\\\u064a\\\\u062f \\\\u0627\\\\u0644\\\\u0633\\\\u0628\\\\u0628.\\\", \\\"\\\\u2022 **\\\\u062a\\\\u062c\\\\u0646\\\\u0628 \\\\u0627\\\\u0644\\\\u0645\\\\u0633\\\\u0643\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0642\\\\u0648\\\\u064a\\\\u0629** \\\\u062f\\\\u0648\\\\u0646 \\\\u0648\\\\u0635\\\\u0641\\\\u0629 \\\\u0637\\\\u0628\\\\u064a\\\\u0629.\\\", \\\"\\\\u2022 **\\\\u0627\\\\u0633\\\\u062a\\\\u062e\\\\u062f\\\\u0645 \\\\u0643\\\\u0645\\\\u0627\\\\u062f\\\\u0627\\\\u062a \\\\u0628\\\\u0627\\\\u0631\\\\u062f\\\\u0629** \\\\u0639\\\\u0644\\\\u0649 \\\\u0627\\\\u0644\\\\u062e\\\\u062f \\\\u0644\\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0627\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0645\\\\u0624\\\\u0642\\\\u062a\\\\u0627\\\\u064b.\\\"]\"','عام','\"[\\\"\\\\u0645\\\\u0646\\\\u0627\\\\u062e\\\\u064a\\\\u0631\\\\u064a\\\", \\\"\\\\u0628\\\\u062a\\\\u0627\\\\u0643\\\\u0644\\\\u0646\\\\u0649\\\", \\\"\\\\u0648\\\\u0639\\\\u064a\\\\u0646\\\\u064a\\\", \\\"\\\\u062a\\\\u062f\\\\u0645\\\\u0639\\\", \\\"\\\\u0633\\\\u0646\\\\u0627\\\\u0646\\\\u0649\\\"]\"',0.95,'deepseek',1,0,0,'2026-04-13 07:22:57','2026-04-13 07:22:57'),(21,'ايه احسن أدوية للبرد','ايه احسن ادويه للبرد','لا يوجد دواء واحد \"أفضل\" لعلاج البرد، حيث أن معظم نزلات البرد تسببها فيروسات وتزول من تلقاء نفسها. العلاج يركز على تخفيف الأعراض مثل الاحتقان والسعال والحمى. من المهم الراحة وشرب السوائل الدافئة بكثرة.','الرعاية المنزلية والعلاجات المساعدة لنزلات البرد','\"[\\\"\\\\u2022  \\\\u0645\\\\u0633\\\\u0643\\\\u0646\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0623\\\\u0644\\\\u0645 \\\\u0648\\\\u062e\\\\u0627\\\\u0641\\\\u0636\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u062d\\\\u0631\\\\u0627\\\\u0631\\\\u0629 \\\\u0645\\\\u062b\\\\u0644 \\\\u0627\\\\u0644\\\\u0628\\\\u0627\\\\u0631\\\\u0627\\\\u0633\\\\u064a\\\\u062a\\\\u0627\\\\u0645\\\\u0648\\\\u0644 \\\\u064a\\\\u0645\\\\u0643\\\\u0646 \\\\u0623\\\\u0646 \\\\u062a\\\\u0633\\\\u0627\\\\u0639\\\\u062f \\\\u0641\\\\u064a \\\\u062a\\\\u062e\\\\u0641\\\\u064a\\\\u0641 \\\\u0627\\\\u0644\\\\u0635\\\\u062f\\\\u0627\\\\u0639 \\\\u0648\\\\u0622\\\\u0644\\\\u0627\\\\u0645 \\\\u0627\\\\u0644\\\\u062c\\\\u0633\\\\u0645 \\\\u0648\\\\u0627\\\\u0644\\\\u062d\\\\u0645\\\\u0649.\\\", \\\"\\\\u2022  \\\\u064a\\\\u0645\\\\u0643\\\\u0646 \\\\u0644\\\\u0645\\\\u0632\\\\u064a\\\\u0644\\\\u0627\\\\u062a \\\\u0627\\\\u0644\\\\u0627\\\\u062d\\\\u062a\\\\u0642\\\\u0627\\\\u0646 (\\\\u0639\\\\u0644\\\\u0649 \\\\u0634\\\\u0643\\\\u0644 \\\\u0623\\\\u0642\\\\u0631\\\\u0627\\\\u0635 \\\\u0623\\\\u0648 \\\\u0628\\\\u062e\\\\u0627\\\\u062e \\\\u0623\\\\u0646\\\\u0641\\\\u064a) \\\\u0623\\\\u0646 \\\\u062a\\\\u062e\\\\u0641\\\\u0641 \\\\u0627\\\\u0646\\\\u0633\\\\u062f\\\\u0627\\\\u062f \\\\u0627\\\\u0644\\\\u0623\\\\u0646\\\\u0641\\\\u060c \\\\u0648\\\\u0644\\\\u0643\\\\u0646 \\\\u064a\\\\u062c\\\\