  `activity_date` date NOT NULL,
  `total_activities` int DEFAULT '0',
  `completed_activities` int DEFAULT '0',
  `work_hours` decimal(5,2) DEFAULT '0.00',
  `study_hours` decimal(5,2) DEFAULT '0.00',
  `exercise_minutes` int DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_date` (`user_id`,`activity_date`),
  KEY `idx_user_date` (`user_id`,`activity_date`),
  CONSTRAINT `daily_activity_stats_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
