DROP TABLE IF EXISTS `food_recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `food_recommendations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `symptom_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'اسم العرض',
  `foods_to_eat` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'أطعمة مفيدة (قائمة)',
  `foods_to_avoid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'أطعمة ممنوعة (قائمة)',
  `drinks_recommended` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'مشروبات مفيدة',
  `drinks_to_avoid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'مشروبات ممنوعة',
  `general_tips` text COLLATE utf8mb4_unicode_ci COMMENT 'نصائح عامة',
  `severity_level` enum('خفيف','متوسط','شديد','الكل') COLLATE utf8mb4_unicode_ci DEFAULT 'الكل',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_symptom` (`symptom_name`),
  KEY `idx_severity` (`severity_level`),
  CONSTRAINT `food_recommendations_chk_1` CHECK (json_valid(`foods_to_eat`)),
  CONSTRAINT `food_recommendations_chk_2` CHECK (json_valid(`foods_to_avoid`)),
  CONSTRAINT `food_recommendations_chk_3` CHECK (json_valid(`drinks_recommended`)),
  CONSTRAINT `food_recommendations_chk_4` CHECK (json_valid(`drinks_to_avoid`))
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
