INSERT INTO `food_recommendations` VALUES (1,'صداع','[\"موز\", \"بطيخ\", \"زنجبيل\", \"شوفان\", \"لوز\", \"سبانخ\", \"سمك\"]','[\"أجبان قديمة\", \"لحوم مصنعة\", \"شوكولاتة\", \"كافيين\", \"أطعمة مالحة\"]','[\"ماء\", \"شاي زنجبيل\", \"عصير بطيخ\", \"شاي نعناع\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','تناول وجبات منتظمة وتجنب الجوع الطويل، اشرب كمية كافية من الماء، تجنب الأطعمة المحفزة للصداع','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(2,'دوخة','[\"زنجبيل\", \"موز\", \"بطاطس\", \"عسل\", \"شوفان\", \"تفاح\"]','[\"أطعمة مالحة\", \"كافيين\", \"كحول\", \"أطعمة دهنية\"]','[\"شاي زنجبيل\", \"ماء جوز الهند\", \"عصير برتقال\", \"شاي نعناع\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','تناول وجبات صغيرة متكررة، اشرب سوائل كافية، تجنب الأطعمة التي تسبب الدوخة','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(3,'غثيان','[\"زنجبيل\", \"موز\", \"تفاح\", \"أرز\", \"خبز محمص\", \"شوربة خضار\"]','[\"أطعمة دهنية\", \"أطعمة حارة\", \"أجبان\", \"لحوم مصنعة\", \"مقليات\"]','[\"شاي زنجبيل\", \"ماء\", \"عصير تفاح\", \"شاي نعناع\"]','[\"قهوة\", \"عصائر حمضية\", \"مشروبات غازية\", \"كحول\"]','تناول أطعمة خفيفة وسهلة الهضم، اشرب سوائل ببطء، تجنب الروائح القوية','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(4,'ألم بطن','[\"موز\", \"أرز\", \"تفاح\", \"خبز محمص\", \"شوربة دافئة\", \"زنجبيل\"]','[\"أطعمة حارة\", \"أطعمة دهنية\", \"بقوليات\", \"مقليات\", \"ألبان\"]','[\"شاي زنجبيل\", \"ماء دافئ\", \"شاي بابونج\", \"عصير تفاح\"]','[\"قهوة\", \"مشروبات غازية\", \"عصائر حمضية\", \"كحول\"]','تناول وجبات صغيرة ومتكررة، تجنب الأطعمة التي تسبب الغازات، استشر طبيبك إذا استمر الألم','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(5,'إسهال','[\"موز\", \"أرز\", \"تفاح\", \"خبز محمص\", \"شوربة جزر\", \"بطاطس مسلوقة\"]','[\"ألبان\", \"أطعمة دهنية\", \"بقوليات\", \"مقليات\", \"خضار نيئة\"]','[\"ماء\", \"شاي بابونج\", \"عصير تفاح\", \"محلول معالجة الجفاف\"]','[\"قهوة\", \"عصائر حمضية\", \"مشروبات غازية\", \"كحول\"]','تجنب الجفاف بشرب السوائل، التزم بنظام BRAT الغذائي (موز، أرز، تفاح، خبز محمص)','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(6,'إمساك','[\"خوخ\", \"توت\", \"برتقال\", \"خضار ورقية\", \"شوفان\", \"بذور الكتان\"]','[\"أطعمة مصنعة\", \"أجبان\", \"لحوم حمراء\", \"موز غير ناضج\", \"أرز أبيض\"]','[\"ماء\", \"عصير خوخ\", \"عصير برتقال\", \"شاي أخضر\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','زد من تناول الألياف والماء، مارس الرياضة بانتظام، تناول أطعمة غنية بالبريبايوتك','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(7,'حرارة','[\"شوربة خضار\", \"فواكه غنية بالماء (بطيخ، برتقال)\", \"زبادي\", \"عسل\"]','[\"أطعمة دهنية\", \"لحوم حمراء\", \"مقليات\", \"أطعمة مالحة\"]','[\"ماء\", \"عصير برتقال\", \"شاي أعشاب\", \"عصير ليمون\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','اشرب سوائل كثيرة لتعويض الفاقد، تناول أطعمة خفيفة، استشر طبيبك إذا استمرت الحرارة','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(8,'ألم صدر','[\"خضار ورقية\", \"أسماك دهنية\", \"زيت زيتون\", \"مكسرات غير مملحة\", \"شوفان\"]','[\"أطعمة دهنية\", \"لحوم حمراء\", \"أطعمة مالحة\", \"مقليات\", \"حلويات\"]','[\"ماء\", \"شاي أخضر\", \"عصير رمان\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','🚨 هذا عرض خطير، استشر الطبيب فوراً. تجنب الأطعمة التي تزيد الالتهاب','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(9,'ضيق تنفس','[\"زنجبيل\", \"ثوم\", \"بصل\", \"خضار ورقية\", \"سمك\", \"زيت زيتون\"]','[\"ألبان\", \"أطعمة دهنية\", \"أطعمة مالحة\", \"لحوم مصنعة\", \"مقليات\"]','[\"ماء\", \"شاي زنجبيل\", \"شاي أخضر\", \"عصير جزر\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','🚨 هذا عرض خطير، استشر الطبيب فوراً. تجنب الأطعمة التي تسبب الحساسية','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(10,'تعب وإرهاق','[\"موز\", \"تمر\", \"شوفان\", \"بيض\", \"عسل\", \"مكسرات\", \"سبانخ\"]','[\"أطعمة سكرية\", \"أطعمة مصنعة\", \"مقليات\", \"كافيين بكميات كبيرة\"]','[\"ماء\", \"عصير برتقال\", \"حليب لوز\", \"شاي أعشاب\"]','[\"مشروبات طاقة\", \"قهوة بكثرة\", \"كحول\"]','تناول وجبات متوازنة، اشرب ماء كافياً، احصل على قسط كاف من النوم','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(11,'زغللة العين','[\"جزر\", \"سبانخ\", \"توت\", \"برتقال\", \"لوز\", \"بيض\"]','[\"أطعمة سكرية\", \"أطعمة مالحة\", \"أطعمة مصنعة\"]','[\"ماء\", \"عصير جزر\", \"شاي أخضر\"]','[\"قهوة\", \"مشروبات غازية\"]','إذا كانت الزغللة مفاجئة، هذا عرض خطير. قلل من السكريات والأطعمة المالحة','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22'),(12,'تنميل الأطراف','[\"موز\", \"بطاطس\", \"أفوكادو\", \"لوز\", \"سبانخ\", \"أسماك\"]','[\"أطعمة سكرية\", \"أطعمة مالحة\", \"كافيين\", \"كحول\"]','[\"ماء\", \"عصير برتقال\", \"حليب جوز الهند\"]','[\"قهوة\", \"مشروبات غازية\", \"كحول\"]','تناول أطعمة غنية بفيتامين ب، اشرب ماء كافياً، استشر طبيب أعصاب إذا استمر التنميل','الكل','2026-03-24 07:50:22','2026-03-24 07:50:22');
/*!40000 ALTER TABLE `food_recommendations` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `foods`
--

DROP TABLE IF EXISTS `foods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `foods` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'اسم الطعام بالعربية',
  `name_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'اسم الطعام بالإنجليزية',
  `calories` float NOT NULL COMMENT 'سعرات حرارية لكل 100 جرام',
  `protein` float DEFAULT '0' COMMENT 'بروتين (جرام)',
  `carbs` float DEFAULT '0' COMMENT 'كربوهيدرات (جرام)',
  `fat` float DEFAULT '0' COMMENT 'دهون (جرام)',
  `fiber` float DEFAULT '0' COMMENT 'ألياف (جرام)',
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '100 جرام' COMMENT 'وحدة القياس',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'التصنيف (كارب - بروتين - خضار - فاكهة - دهون - مشروبات)',
  `icon` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '?️',
  `suitable_for` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'مناسب لمرضى (السكري, الضغط, ...)',
  `is_recommended` tinyint(1) DEFAULT '0',
  `glycemic_index` int DEFAULT NULL COMMENT 'مؤشر سكري (للمقارنة)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_calories` (`calories`),
  KEY `idx_is_recommended` (`is_recommended`),
  CONSTRAINT `foods_chk_1` CHECK (json_valid(`suitable_for`))
) ENGINE=InnoDB AUTO_INCREMENT=168 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `foods`
--

LOCK TABLES `foods` WRITE;
/*!40000 ALTER TABLE `foods` DISABLE KEYS */;
