--
-- Table structure for table `health_impact_factors`
--

DROP TABLE IF EXISTS `health_impact_factors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `health_impact_factors` (
  `id` int NOT NULL AUTO_INCREMENT,
  `factor_type` enum('symptom','medicine','disease') COLLATE utf8mb4_unicode_ci NOT NULL,
  `factor_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `impact_on_steps` int NOT NULL COMMENT 'نسبة التأثير على هدف الخطوات (بالنسبة المئوية - سالب للتقليل، موجب للزيادة)',
  `calories_adjustment` int DEFAULT NULL COMMENT 'تعديل السعرات (بالمئوية)',
  `severity_level` enum('خفيف','متوسط','شديد','الكل') COLLATE utf8mb4_unicode_ci DEFAULT 'الكل',
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_factor` (`factor_type`,`factor_name`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

