INSERT INTO `health_impact_factors` VALUES (1,'symptom','صداع',-20,0,'خفيف','الصداع الخفيف يقلل النشاط قليلاً','2026-03-24 08:54:58'),(2,'symptom','صداع',-40,-5,'متوسط','الصداع المتوسط يقلل النشاط والنشاط البدني','2026-03-24 08:54:58'),(3,'symptom','صداع',-70,-10,'شديد','الصداع الشديد يمنع النشاط البدني','2026-03-24 08:54:58'),(4,'symptom','دوخة',-50,-10,'','الدوخة تجعل المشي غير آمن','2026-03-24 08:54:58'),(5,'symptom','ألم صدر',-90,-20,'','ألم الصدر يمنع النشاط البدني','2026-03-24 08:54:58'),(6,'symptom','ضيق تنفس',-80,-15,'','ضيق التنفس يمنع النشاط البدني','2026-03-24 08:54:58'),(7,'symptom','حمى',-60,-10,'','الحرارة تسبب إرهاقاً وتقلل النشاط','2026-03-24 08:54:58'),(8,'symptom','تعب وإرهاق',-40,-5,'خفيف','التعب الخفيف يقلل النشاط','2026-03-24 08:54:58'),(9,'symptom','تعب وإرهاق',-60,-10,'متوسط','التعب المتوسط يقلل النشاط','2026-03-24 08:54:58'),(10,'symptom','تعب وإرهاق',-80,-15,'شديد','التعب الشديد يمنع النشاط','2026-03-24 08:54:58'),(11,'symptom','غثيان',-30,-5,'','الغثيان يقلل الرغبة في الحركة','2026-03-24 08:54:58'),(12,'symptom','ألم بطن',-40,-5,'','ألم البطن يقلل النشاط','2026-03-24 08:54:58'),(13,'symptom','إسهال',-50,-10,'','الإسهال يسبب جفافاً ويقلل النشاط','2026-03-24 08:54:58'),(14,'symptom','إمساك',-20,0,'','الإمساك يقلل النشاط قليلاً','2026-03-24 08:54:58'),(15,'symptom','زغللة العين',-70,-10,'','زغللة العين تجعل المشي غير آمن','2026-03-24 08:54:58'),(16,'symptom','تنميل الأطراف',-50,-5,'','التنميل يقلل التوازن','2026-03-24 08:54:58'),(17,'symptom','آلام العضلات',-30,0,'خفيف','آلام العضلات الخفيفة','2026-03-24 08:54:58'),(18,'symptom','آلام العضلات',-50,-5,'متوسط','آلام العضلات المتوسطة','2026-03-24 08:54:58'),(19,'symptom','آلام العضلات',-70,-10,'شديد','آلام العضلات الشديدة','2026-03-24 08:54:58'),(20,'disease','السكري',10,0,'','مرضى السكري يحتاجون حركة أكثر','2026-03-24 08:54:58'),(21,'disease','ضغط الدم',5,0,'','المشي مفيد لمرضى الضغط','2026-03-24 08:54:58'),(22,'disease','القلب',-20,-5,'','مرضى القلب يحتاجون مشي معتدل','2026-03-24 08:54:58'),(23,'disease','الكوليسترول',15,0,'','المشي يساعد في خفض الكوليسترول','2026-03-24 08:54:58'),(24,'disease','الربو',-10,0,'','الربو قد يحد من النشاط','2026-03-24 08:54:58'),(25,'disease','الروماتيزم',-30,-5,'','آلام المفاصل تحد من النشاط','2026-03-24 08:54:58'),(26,'disease','الأنيميا',-40,-5,'','الأنيميا تسبب تعباً وإرهاقاً','2026-03-24 08:54:58'),(27,'disease','الغدة الدرقية',-20,-5,'','قصور الغدة يقلل الطاقة','2026-03-24 08:54:58'),(28,'medicine','جلوكوفاج',5,0,'','الجلوكوفاج يساعد في تحسين الطاقة','2026-03-24 08:54:58'),(29,'medicine','كونكور',-20,-5,'','حاصرات بيتا قد تسبب تعباً','2026-03-24 08:54:58'),(30,'medicine','فولتارين',-10,0,'','قد يسبب تخفيف الألم يسمح بزيادة النشاط','2026-03-24 08:54:58'),(31,'medicine','أوميغا 3',10,0,'','يحسن صحة القلب والطاقة','2026-03-24 08:54:58'),(32,'medicine','باراسيتامول',5,0,'','تخفيف الألم يسمح بزيادة النشاط','2026-03-24 08:54:58'),(33,'medicine','بانادول',5,0,'الكل','تخفيف الألم يسمح بزيادة النشاط','2026-04-18 16:31:23'),(34,'medicine','بروفين',-10,0,'الكل','قد يسبب اضطرابات معوية تقلل النشاط','2026-04-18 16:31:23'),(35,'medicine','سيتال',5,0,'الكل','تخفيف الألم يسمح بزيادة النشاط','2026-04-18 16:31:23'),(36,'medicine','ترامادول',-40,-10,'الكل','يسبب دوخة ونعاس شديد يقلل النشاط','2026-04-18 16:31:23'),(37,'medicine','لافوكس',10,5,'الكل','تحسين المزاج يزيد الطاقة والرغبة في الحركة','2026-04-18 16:31:23'),(38,'medicine','زاناكس',-50,-10,'الكل','يسبب نعاس شديد ودوخة يمنع النشاط','2026-04-18 16:31:23'),(39,'medicine','ريسبيريدون',-30,-5,'الكل','يسبب زيادة وزن وخمول','2026-04-18 16:31:23'),(40,'medicine','كلونازيبام',-50,-10,'الكل','يسبب ضعف عضلي ونعاس شديد','2026-04-18 16:31:23'),(41,'medicine','إيزوميبرازول',0,0,'الكل','لا تأثير مباشر على النشاط','2026-04-18 16:31:23'),(42,'medicine','سبازموفين',-10,0,'الكل','قد يسبب دوخة خفيفة','2026-04-18 16:31:23'),(43,'medicine','دوفاستون',-10,0,'الكل','قد يسبب تعب وتقلبات مزاجية','2026-04-18 16:31:23'),(44,'medicine','كلوميد',-10,-5,'الكل','قد يسبب تعب وهبات ساخنة','2026-04-18 16:31:23'),(45,'medicine','ليفوثيروكسين',20,10,'الكل','تحسن الطاقة والنشاط','2026-04-18 16:31:23'),(46,'medicine','ديكلوفيناك',-10,0,'الكل','قد يسبب اضطرابات معوية','2026-04-18 16:31:23'),(47,'medicine','كيتوبروفين',-10,0,'الكل','قد يسبب اضطرابات معوية','2026-04-18 16:31:23'),(48,'medicine','ميلوكسيكام',-5,0,'الكل','تأثير معتدل على النشاط','2026-04-18 16:31:23'),(49,'medicine','بروبرانولول',-25,-5,'الكل','يسبب تعب وبطء نبض','2026-04-18 16:31:23'),(50,'medicine','أتورفاستاتين',-15,-5,'الكل','قد يسبب ألم عضلي','2026-04-18 16:31:23'),(51,'medicine','سيمفاستاتين',-15,-5,'الكل','قد يسبب ألم عضلي','2026-04-18 16:31:23'),(52,'medicine','سبيرونولاكتون',-10,0,'الكل','قد يسبب تعب ودوخة','2026-04-18 16:31:23'),(53,'medicine','فوروسيميد',-20,-5,'الكل','كثرة التبول والتعب يقلل النشاط','2026-04-18 16:31:23'),(54,'medicine','سيلدينافيل',15,5,'الكل','تحسن الدورة الدموية يزيد الطاقة','2026-04-18 16:31:23'),(55,'medicine','تادالافيل',15,5,'الكل','تحسن الدورة الدموية يزيد الطاقة','2026-04-18 16:31:23');
