INSERT INTO `medicine_food_recommendations` VALUES (1,1,'جلوكوفاج','[\"أطعمة غنية بالسكريات\", \"عصائر محلاة\", \"حلويات\", \"مشروبات غازية\"]','[\"خضروات ورقية\", \"شوفان\", \"عدس\", \"فول\", \"أسماك\"]','[\"عصائر محلاة\", \"مشروبات غازية\", \"كحول\"]','[\"ماء\", \"شاي أخضر\", \"قرفة\"]','يؤخذ مع الأكل لتجنب اضطرابات المعدة','تجنب الكحول أثناء العلاج، اشرب ماء كافياً','2026-03-24 08:54:57','2026-03-24 08:54:57'),(2,2,'لستينوبريل','[\"أطعمة غنية بالبوتاسيوم (موز، بطاطس، أفوكادو)\", \"أطعمة مالحة\", \"بدائل الملح\"]','[\"خضروات\", \"فواكه قليلة البوتاسيوم\", \"أسماك\"]','[\"عصير برتقال\", \"كحول\"]','[\"ماء\", \"شاي أعشاب\"]','يؤخذ في نفس الوقت يومياً، مع أو بدون طعام','تجنب بدائل الملح التي تحتوي على بوتاسيوم','2026-03-24 08:54:57','2026-03-24 08:54:57'),(3,3,'أموكسيسيلين','[\"ألبان\", \"أجبان\", \"زبادي\", \"أطعمة حامضية\"]','[\"خضروات\", \"فواكه\", \"بروتينات خفيفة\"]','[\"عصائر حمضية\", \"كحول\"]','[\"ماء\", \"شاي أعشاب\"]','يمكن تناوله مع أو بدون طعام','تجنب منتجات الألبان قبل وبعد ساعتين من الدواء','2026-03-24 08:54:57','2026-03-24 08:54:57'),(4,4,'باراسيتامول','[\"أطعمة دهنية\", \"مقليات\", \"كحول\"]','[\"خضروات\", \"فواكه\", \"شوربات\"]','[\"كحول\", \"قهوة بكميات كبيرة\"]','[\"ماء\", \"شاي أعشاب\"]','يمكن تناوله مع أو بدون طعام','لا تتجاوز الجرعة الموصى بها، تجنب الكحول','2026-03-24 08:54:57','2026-03-24 08:54:57'),(5,5,'فولتارين','[\"أطعمة حارة\", \"بهارات\", \"أطعمة دهنية\", \"ألبان\"]','[\"خضروات\", \"أرز\", \"شوربات خفيفة\"]','[\"كحول\", \"قهوة\", \"مشروبات غازية\"]','[\"ماء\", \"حليب\", \"شاي بابونج\"]','يؤخذ بعد الأكل مع كوب ماء','تجنب الكحول والأطعمة الحارة لتقليل تهيج المعدة','2026-03-24 08:54:57','2026-03-24 08:54:57'),(6,6,'أوميغا 3','[\"أطعمة دهنية مشبعة\", \"مقليات\"]','[\"أسماك دهنية\", \"مكسرات\", \"بذور الكتان\"]','[\"كحول\"]','[\"ماء\", \"شاي أخضر\"]','يؤخذ مع الوجبات','يخزن في الثلاجة بعد الفتح','2026-03-24 08:54:57','2026-03-24 08:54:57'),(7,7,'زيماكس','[\"ألبان\", \"أجبان\", \"أطعمة دهنية\"]','[\"خضروات\", \"فواكه\", \"بروتينات خفيفة\"]','[