INSERT INTO `medicines` VALUES (1,'جلوكوفاج','Glucophage','ميتفورمين',NULL,'أدوية السكري','يستخدم لعلاج مرض السكري من النوع الثاني','\"[\\\"\\\\u0639\\\\u0644\\\\u0627\\\\u062c \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631\\\\u064a \\\\u0645\\\\u0646 \\\\u0627\\\\u0644\\\\u0646\\\\u0648\\\\u0639 \\\\u0627\\\\u0644\\\\u062b\\\\u0627\\\\u0646\\\\u064a\\\", \\\"\\\\u062e\\\\u0641\\\\u0636 \\\\u0645\\\\u0633\\\\u062a\\\\u0648\\\\u0649 \\\\u0627\\\\u0644\\\\u0633\\\\u0643\\\\u0631 \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u062f\\\\u0645\\\", \\\"\\\\u062a\\\\u062d\\\\u0633\\\\u064a\\\\u0646 \\\\u062d\\\\u0633\\\\u0627\\\\u0633\\\\u064a\\\\u0629 \\\\u0627\\\\u0644\\\\u0623\\\\u0646\\\\u0633\\\\u0648\\\\u0644\\\\u064a\\\\u0646\\\", \\\"\\\\u0639\\\\u0644\\\\u0627\\\\u062c \\\\u0645\\\\u062a\\\\u0644\\\\u0627\\\\u0632\\\\u0645\\\\u0629 \\\\u062a\\\\u0643\\\\u064a\\\\u0633 \\\\u0627\\\\u0644\\\\u0645\\\\u0628\\\\u0627\\\\u064a\\\\u0636\\\"]\"','\"[\\\"\\\\u063a\\\\u062b\\\\u064a\\\\u0627\\\\u0646\\\", \\\"\\\\u0625\\\\u0633\\\\u0647\\\\u0627\\\\u0644\\\", \\\"\\\\u0641\\\\u0642\\\\u062f\\\\u0627\\\\u0646 \\\\u0634\\\\u0647\\\\u064a\\\\u0629\\\", \\\"\\\\u0637\\\\u0639\\\\u0645 \\\\u0645\\\\u0639\\\\u062f\\\\u0646\\\\u064a \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0641\\\\u0645\\\", \\\"\\\\u0627\\\\u0636\\\\u0637\\\\u0631\\\\u0627\\\\u0628\\\\u0627\\\\u062a \\\\u0641\\\\u064a \\\\u0627\\\\u0644\\\\u0645\\\\u0639\\\\u062f\\\\u0629\\\"]\"','\"[\\\"\\\\u0644\\\\u0627 \\\\u062a\\\\u062a\\\\u0648\\\\u0642\\\\u0641 \\\\u0639\\\\u0646 \\\\u0627\\\\u0644\\\\u062f\\\\u0648\\\\u0627\\\\u0621 \\\\u062f\\\\u0648\\\\u0646 \\\\u0627\\\\u0633\\\\u062a\\\\u0634\\\\u0627\\\\u0631\\\\u0629 \\\\u0627\\\\u0644\\\\u0637\\\\u0628\\\\u064a\\\\u0628\\\", \\\"\\\\u0642\\\\u062f \\\\u064a\\\\u0633\\\\u0628\\\\u0628 \\\\u0627\\\\u0644\\\\u062d\\\\u0645\\\\u0627\\\\u0636 \\\\u0627\\\\u0644\\\\u0644\\\\u0628\\\\u0646\\\\u064a \\\\u0641\\\\u064a \\\\u062d\\\\u0627\\\\u0644\\\\u0627\\\\u062a \\\\u0646\\\\u