INSERT INTO `symptom_tips` VALUES (1,1,'الكل','علاج منزلي','علاج الصداع في المنزل','','استرح في غرفة مظلمة وهادئة، اشرب ماء، تجنب الشاشات، استخدم كمادات باردة على الجبهة.','','🧊',5,'2026-03-10 04:25:12'),(2,1,'شديد','متى تزور الطبيب','متى تزور الطبيب للصداع','','إذا كان الصداع شديداً ومفاجئاً، أو مصحوباً بزغللة أو تيبس في الرقبة، توجه للطوارئ.','','🚨',10,'2026-03-10 04:25:12'),(3,2,'الكل','علاج منزلي','علاج الدوخة','','اجلس أو استلق فوراً، اشرب ماء، تناول وجبة خفيفة إذا كنت جائعاً، قس السكر إذا كنت مريض سكري.','','💧',5,'2026-03-10 04:25:12'),(4,4,'شديد','عام','تحذير: ألم الصدر','','🚨 ألم الصدر عرض خطير. إذا كنت تعاني من ألم في الصدر مع عرق غزير أو ضيق تنفس، اتصل بالطوارئ فوراً.','','⚠️',10,'2026-03-10 04:25:12'),(5,5,'شديد','عام','تحذير: ضيق التنفس','','🚨 ضيق التنفس المفاجئ يحتاج تدخلاً طبياً فورياً. اجلس في وضع مريح واتصل بالطوارئ.','','🆘',10,'2026-03-10 04:25:12'),(6,3,'متوسط','علاج منزلي','علاج الغثيان','','تناول وجبات خفيفة، اشرب سوائل ببطء، تجنب الروائح القوية، استرح.','','🍵',5,'2026-03-10 04:25:12'),(7,6,'الكل','علاج منزلي','خفض الحرارة','','اشرب سوائل كثيرة، استخدم كمادات ماء فاتر، تناول خافض حرارة بعد استشارة الطبيب.','','🌡️',5,'2026-03-10 04:25:12');
/*!40000 ALTER TABLE `symptom_tips` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `symptom_types`
--

DROP TABLE IF EXISTS `symptom_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `symptom_types` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name_ar` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'اسم العرض بالعربية',
  `name_en` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'اسم العرض بالإنجليزية',
  `icon` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '?' COMMENT 'أيقونة العرض',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'التصنيف (عصبي - هضمي - تنفسي - ...)',
  `default_analysis` text COLLATE utf8mb4_unicode_ci COMMENT 'تحليل افتراضي لهذا النوع من الأعراض',
  `common_causes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'الأسباب الشائعة بصيغة JSON',
  `recommended_actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'الإجراءات الموصى بها بصيغة JSON',
  `warning_signs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'علامات الخطر',
  `requires_immediate_care` tinyint(1) DEFAULT '0' COMMENT 'هل يحتاج عناية فورية؟',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_name_ar` (`name_ar`),
  UNIQUE KEY `unique_name_en` (`name_en`),
  CONSTRAINT `symptom_types_chk_1` CHECK (json_valid(`common_causes`)),
  CONSTRAINT `symptom_types_chk_2` CHECK (json_valid(`recommended_actions`)),
  CONSTRAINT `symptom_types_chk_3` CHECK (json_valid(`warning_signs`))
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

