/*!40000 ALTER TABLE `symptom_types` DISABLE KEYS */;
INSERT INTO `symptom_types` VALUES (1,'صداع','Headache','🤕','عصبي','الصداع قد يكون نتيجة للإجهاد، الجفاف، أو ارتفاع ضغط الدم. إذا كان مصحوباً بزغللة أو دوخة، قد يشير لارتفاع الضغط.','[\"الإجهاد والتعب\", \"الجفاف\", \"ارتفاع ضغط الدم\", \"الصداع النصفي\", \"إجهاد العين\"]','[\"قس ضغط الدم\", \"اشرب كمية كافية من الماء\", \"استرح في مكان هادئ ومظلم\", \"تجنب الشاشات (الهاتف - التلفاز)\"]','[\"صداع مفاجئ وشديد\", \"صداع مع تيبس في الرقبة\", \"صداع بعد إصابة في الرأس\", \"صداع مع ضعف في الأطراف\"]',0,'2026-03-10 04:25:12'),(2,'دوخة','Dizziness','😵','عصبي','الدوخة قد تكون بسبب انخفاض السكر، الجفاف، أو مشاكل في الأذن الداخلية. إذا كانت مصحوبة بطنين أو فقدان توازن، قد تشير لمشكلة في الأذن.','[\"انخفاض السكر\", \"الجفاف\", \"مشاكل الأذن الداخلية\", \"فقر الدم\", \"القلق والتوتر\"]','[\"قس السكر إذا كنت مريض سكري\", \"اشرب ماء\", \"اجلس أو استلق فوراً\", \"تناول وجبة خفيفة\"]','[\"دوخة مع فقدان الوعي\", \"دوخة مع ألم في الصدر\", \"دوخة مع تداخل في الكلام\", \"دوخة مستمرة لساعات\"]',0,'2026-03-10 04:25:12'),(3,'غثيان','Nausea','🤢','هضمي','الغثيان قد يكون بسبب عسر هضم، تسمم غذائي، أو دوار الحركة. إذا كان مصحوباً بقيء شديد، قد يؤدي للجفاف.','[\"عسر الهضم\", \"تسمم غذائي\", \"دوار الحركة\", \"الحمل\", \"الصداع النصفي\"]','[\"تناول وجبات خفيفة\", \"تجنب الأطعمة الدهنية\", \"اشرب سوائل ببطء\", \"استرح\"]','[\"قيء مستمر\", \"قيء دموي\", \"ألم شديد في البطن\", \"جفاف شديد\"]',0,'2026-03-10 04:25:12'),(4,'ألم صدر','Chest Pain','💔','قلبي','🚨 هذا عرض خطير قد يشير لمشكلة في القلب. يجب التوجه للطوارئ فوراً خاصة إذا كان مصحوباً بعرق غزير أو ضيق تنفس.','[\"مشاكل القلب\", \"القلق\", \"مشاكل الجهاز التنفسي\", \"ارتجاع المريء\"]','[\"اتصل بالطوارئ فوراً\", \"لا تقم بقيادة السيارة\", \"اجلس في وضع مريح\", \"حاول أن تهدأ\"]','[\"ألم يمتد للذراع أو الفك\", \"ضيق في التنفس\", \"عرق بارد\", \"غثيان وقيء\"]',1,'2026-03-10 04:25:12'),(5,'ضيق تنفس','Shortness of Breath','😮‍💨','تنفسي','🚨 ضيق التنفس عرض خطير قد يشير لمشكلة في القلب أو الرئتين. يحتاج تقييماً طبياً فورياً.','[\"الربو\", \"الانسداد الرئوي\", \"قصور القلب\", \"القلق\", \"فقر الدم\"]','[\"اتصل بالطوارئ\", \"اجلس في وضع مستقيم\", \"حاول التنفس ببطء\", \"استخدم بخاخ الربو إن وجد\"]','[\"ألم في الصدر\", \"ازرقاق الشفاه\", \"عدم القدرة على التحدث\", \"دوخة شديدة\"]',1,'2026-03-10 04:25:12'),(6,'حرارة','Fever','🌡️','عام','ارتفاع الحرارة قد يشير لوجود التهاب في الجسم. إذا استمرت أكثر من 3 أيام أو كانت مرتفعة جداً، استشر طبيبك.','[\"عدوى فيروسية\", \"عدوى بكتيرية\", \"التهاب\", \"ضربة شمس\"]','[\"قس درجة الحرارة\", \"اشرب سوائل كثيرة\", \"استخدم كمادات\", \"تناول خافض حرارة\"]','[\"حرارة أعلى من 40°م\", \"حرارة مع تيبس رقبة\", \"حرارة مع طفح جلدي\", \"حرارة مستمرة لأكثر من 3 أيام\"]',0,'2026-03-10 04:25:12'),(7,'ألم بطن','Abdominal Pain','🫄','هضمي','ألم البطن قد يكون بسبب عسر هضم، إمساك، أو التهاب. إذا كان شديداً أو مصحوباً بحرارة، استشر طبيبك.','[\"عسر هضم\", \"إمساك\", \"التهاب المعدة\", \"متلازمة القولون العصبي\", \"حصوات المرارة\"]','[\"تجنب الأطعمة الدسمة\", \"اشرب سوائل دافئة\", \"استرح\", \"تناول وجبات خفيفة\"]','[\"ألم شديد ومفاجئ\", \"ألم مع حرارة\", \"قيء دموي\", \"انتفاخ شديد\"]',0,'2026-03-10 04:25:12'),(8,'إسهال','Diarrhea','🚽','هضمي','الإسهال قد يكون بسبب عدوى فيروسية أو بكتيرية. المهم تعويض السوائل المفقودة لتجنب الجفاف.','[\"عدوى فيروسية\", \"تسمم غذائي\", \"حساسية غذائية\", \"التهاب القولون\", \"أدوية معينة\"]','[\"اشرب سوائل كثيرة\", \"تجنب منتجات الألبان\", \"تناول أطعمة خفيفة\", \"استشر طبيباً إذا استمر\"]','[\"إسهال دموي\", \"إسهال مع حرارة\", \"جفاف شديد\", \"إسهال مستمر لأكثر من 3 أيام\"]',0,'2026-03-10 04:25:12'),(9,'تنميل','Numbness','🫨','عصبي','التنميل قد يكون بسبب نقص فيتامينات، أو مشاكل في الأعصاب. إذا كان في جانب واحد، قد يشير لمشكلة خطيرة.','[\"نقص فيتامين ب12\", \"الضغط على العصب\", \"السكري\", \"نقص الدورة الدموية\"]','[\"تحقق من نسبة السكر\", \"حرك المنطقة المصابة\", \"استشر طبيب أعصاب\", \"تناول أطعمة غنية بفيتامين ب\"]','[\"تنميل في جانب واحد\", \"تنميل مفاجئ\", \"تنميل مع ضعف\", \"تنميل بعد إصابة\"]',0,'2026-03-10 04:25:12'),(10,'زغللة','Blurred Vision','👁️','بصري','زغللة العين قد تكون بسبب إجهاد العين، أو قد تشير لارتفاع السكر أو الضغط. إذا كانت مفاجئة، فهي حالة طارئة.','[\"إجهاد العين\", \"ارتفاع السكر\", \"ارتفاع الضغط\", \"الصداع النصفي\", \"مشاكل في النظر\"]','[\"قس السكر\", \"قس الضغط\", \"أرح عينيك\", \"تجنب الشاشات\"]','[\"زغللة مفاجئة\", \"زغللة مع صداع شديد\", \"فقدان البصر المفاجئ\", \"رؤية أضواء وامضة\"]',1,'2026-03-10 04:25:12'),(11,'تعب','Fatigue','😴','عام','التعب المستمر قد يكون بسبب فقر الدم، اضطرابات النوم، أو مشاكل الغدة الدرقية. إذا استمر لأكثر من أسبوعين، استشر طبيبك.','[\"فقر الدم\", \"قلة النوم\", \"الغدة الدرقية\", \"الاكتئاب\", \"الإجهاد\"]','[\"نم 7-8 ساعات\", \"تناول غذاء متوازن\", \"مارس الرياضة\", \"اشرب ماء كافياً\"]','[\"تعب شديد ومفاجئ\", \"تعب مع فقدان وزن\", \"تعب مع حرارة\", \"تعب يمنع الأنشطة اليومية\"]',0,'2026-03-10 04:25:12');
/*!40000 ALTER TABLE `symptom_types` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `symptoms`
--

DROP TABLE IF EXISTS `symptoms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `symptoms` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '?',
  `severity` enum('خفيف','متوسط','شديد') COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_time` datetime NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `analysis` text COLLATE utf8mb4_unicode_ci,
  `possible_causes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `suggested_actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `warning_signs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `food_recommendations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_severity` (`severity`),
  KEY `idx_date_time` (`date_time`),
  CONSTRAINT `symptoms_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `symptoms_chk_1` CHECK (json_valid(`possible_causes`)),
  CONSTRAINT `symptoms_chk_2` CHECK (json_valid(`suggested_actions`)),
  CONSTRAINT `symptoms_chk_3` CHECK (json_valid(`warning_signs`)),
  CONSTRAINT `symptoms_chk_4` CHECK (json_valid(`food_recommendations`))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `symptoms`
--

LOCK TABLES `symptoms` WRITE;
/*!40000 ALTER TABLE `symptoms` DISABLE KEYS */;
INSERT INTO `symptoms` VALUES (4,6,'زغللة','👁️','خفيف','2026-03-30 08:01:00','','هذا العرض (زغللة) يحتاج متابعة. إذا استمر، استشر طبيبك.','[\"\\u0633\\u0628\\u0628 \\u0645\\u062d\\u062a\\u0645\\u0644 1\", \"\\u0633\\u0628\\u0628 \\u0645\\u062d\\u062a\\u0645\\u0644 2\", \"\\u0633\\u0628\\u0628 \\u0645\\u062d\\u062a\\u0645\\u0644 3\"]','[\"\\u0631\\u0627\\u0642\\u0628 \\u0627\\u0644\\u0623\\u0639\\u0631\\u0627\\u0636\", \"\\u0627\\u0633\\u062a\\u0634\\u0631 \\u0637\\u0628\\u064a\\u0628\\u0627\\u064b\", \"\\u062e\\u0630 \\u0642\\u0633\\u0637\\u0627\\u064b \\u0645\\u0646 \\u0627\\u0644\\u0631\\u0627\\u062d\\u0629\"]','[\"\\u0625\\u0630\\u0627 \\u0627\\u0632\\u062f\\u0627\\u062f\\u062a \\u0634\\u062f\\u062a\\u0647\", \"\\u0625\\u0630\\u0627 \\u0638\\u0647\\u0631\\u062a \\u0623\\u0639\\u0631\\u0627\\u0636 \\u062c\\u062f\\u064a\\u062f\\u0629\", \"\\u0625\\u0630\\u0627 \\u0627\\u0633\\u062a\\u0645\\u0631 \\u0644\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 3 \\u0623\\u064a\\u0627\\u0645\"]','{\"foods_to_eat\": [\"\\u062e\\u0636\\u0631\\u0648\\u0627\\u062a \\u0637\\u0627\\u0632\\u062c\\u0629\", \"\\u0641\\u0648\\u0627\\u0643\\u0647\", \"\\u0628\\u0631\\u0648\\u062a\\u064a\\u0646\\u0627\\u062a \\u062e\\u0641\\u064a\\u0641\\u0629\"], \"foods_to_avoid\": [\"\\u0623\\u0637\\u0639\\u0645\\u0629 \\u062f\\u0633\\u0645\\u0629\", \"\\u0645\\u0642\\u0644\\u064a\\u0627\\u062a\", \"\\u0623\\u0637\\u0639\\u0645\\u0629 \\u0645\\u0635\\u0646\\u0639\\u0629\"], \"drinks_recommended\": [\"\\u0645\\u0627\\u0621\", \"\\u0634\\u0627\\u064a \\u0623\\u0639\\u0634\\u0627\\u0628\"], \"drinks_to_avoid\": [\"\\u0645\\u0634\\u0631\\u0648\\u0628\\u0627\\u062a \\u063a\\u0627\\u0632\\u064a\\u0629\", \"\\u0642\\u0647\\u0648\\u0629 \\u0628\\u0643\\u062b\\u0631\\u0629\"], \"general_tips\": \"\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0637\\u0639\\u0627\\u0645 \\u0635\\u062d\\u064a \\u0645\\u062a\\u0648\\u0627\\u0632\\u0646\\u060c \\u0627\\u0634\\u0631\\u0628 \\u0643\\u0645\\u064a\\u0629 \\u0643\\u0627\\u0641\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0627\\u0621\"}','2026-03-30 06:01:35','2026-03-30 06:01:35'),(5,6,'حرارة','🌡️','متوسط','2026-03-30 08:02:00','','ارتفاع الحرارة قد يشير لوجود التهاب في الجسم.','[\"\\u0639\\u062f\\u0648\\u0649 \\u0641\\u064a\\u0631\\u0648\\u0633\\u064a\\u0629\", \"\\u0639\\u062f\\u0648\\u0649 \\u0628\\u0643\\u062a\\u064a\\u0631\\u064a\\u0629\", \"\\u0627\\u0644\\u062a\\u0647\\u0627\\u0628\", \"\\u0636\\u0631\\u0628\\u0629 \\u0634\\u0645\\u0633\"]','[\"\\u0642\\u0633 \\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u062d\\u0631\\u0627\\u0631\\u0629\", \"\\u0627\\u0634\\u0631\\u0628 \\u0633\\u0648\\u0627\\u0626\\u0644 \\u0643\\u062b\\u064a\\u0631\\u0629\", \"\\u0627\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0643\\u0645\\u0627\\u062f\\u0627\\u062a\", \"\\u062a\\u0646\\u0627\\u0648\\u0644 \\u062e\\u0627\\u0641\\u0636 \\u062d\\u0631\\u0627\\u0631\\u0629\"]','[\"\\u062d\\u0631\\u0627\\u0631\\u0629 \\u0623\\u0639\\u0644\\u0649 \\u0645\\u0646 40\\u00b0\\u0645\", \"\\u062d\\u0631\\u0627\\u0631\\u0629 \\u0645\\u0639 \\u062a\\u064a\\u0628\\u0633 \\u0631\\u0642\\u0628\\u0629\", \"\\u062d\\u0631\\u0627\\u0631\\u0629 \\u0645\\u0639 \\u0637\\u0641\\u062d \\u062c\\u0644\\u062f\\u064a\", \"\\u062d\\u0631\\u0627\\u0631\\u0629 \\u0645\\u0633\\u062a\\u0645\\u0631\\u0629 \\u0644\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 3 \\u0623\\u064a\\u0627\\u0645\"]','{\"foods_to_eat\": [\"\\u0634\\u0648\\u0631\\u0628\\u0629 \\u062e\\u0636\\u0627\\u0631\", \"\\u0641\\u0648\\u0627\\u0643\\u0647 \\u063a\\u0646\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0627\\u0621 (\\u0628\\u0637\\u064a\\u062e\\u060c \\u0628\\u0631\\u062a\\u0642\\u0627\\u0644)\", \"\\u0632\\u0628\\u0627\\u062f\\u064a\", \"\\u0639\\u0633\\u0644\"], \"foods_to_avoid\": [\"\\u0623\\u0637\\u0639\\u0645\\u0629 \\u062f\\u0647\\u0646\\u064a\\u0629\", \"\\u0644\\u062d\\u0648\\u0645 \\u062d\\u0645\\u0631\\u0627\\u0621\", \"\\u0645\\u0642\\u0644\\u064a\\u0627\\u062a\", \"\\u0623\\u0637\\u0639\\u0645\\u0629 \\u0645\\u0627\\u0644\\u062d\\u0629\"], \"drinks_recommended\": [\"\\u0645\\u0627\\u0621\", \"\\u0639\\u0635\\u064a\\u0631 \\u0628\\u0631\\u062a\\u0642\\u0627\\u0644\", \"\\u0634\\u0627\\u064a \\u0623\\u0639\\u0634\\u0627\\u0628\", \"\\u0639\\u0635\\u064a\\u0631 \\u0644\\u064a\\u0645\\u0648\\u0646\"], \"drinks_to_avoid\": [\"\\u0642\\u0647\\u0648\\u0629\", \"\\u0645\\u0634\\u0631\\u0648\\u0628\\u0627\\u062a \\u063a\\u0627\\u0632\\u064a\\u0629\", \"\\u0643\\u062d\\u0648\\u0644\"], \"general_tips\": \"\\u0627\\u0634\\u0631\\u0628 \\u0633\\u0648\\u0627\\u0626\\u0644 \\u0643\\u062b\\u064a\\u0631\\u0629 \\u0644\\u062a\\u0639\\u0648\\u064a\\u0636 \\u0627\\u0644\\u0641\\u0627\\u0642\\u062f\\u060c \\u062a\\u0646\\u0627\\u0648\\u0644 \\u0623\\u0637\\u0639\\u0645\\u0629 \\u062e\\u0641\\u064a\\u0641\\u0629\\u060c \\u0627\\u0633\\u062a\\u0634\\u0631 \\u0637\\u0628\\u064a\\u0628\\u0643 \\u0625\\u0630\\u0627 \\u0627\\u0633\\u062a\\u0645\\u0631\\u062a \\u0627\\u0644\\u062d\\u0631\\u0627\\u0631\\u0629\"}','2026-03-30 06:02:53','2026-03-30 06:02:53'),(6,6,'صداع','🤕','متوسط','2026-04-02 16:59:00','','الصداع قد يكون نتيجة للإجهاد، الجفاف، أو ارتفاع ضغط الدم.','[\"\\u0627\\u0644\\u0625\\u062c\\u0647\\u0627\\u062f \\u0648\\u0627\\u0644\\u062a\\u0639\\u0628\", \"\\u0627\\u0644\\u062c\\u0641\\u0627\\u0641\", \"\\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0636\\u063a\\u0637 \\u0627\\u0644\\u062f\\u0645\", \"\\u0627\\u0644\\u0635\\u062f\\u0627\\u0639 \\u0627\\u0644\\u0646\\u0635\\u0641\\u064a\", \"\\u0625\\u062c\\u0647\\u0627\\u062f \\u0627\\u0644\\u0639\\u064a\\u0646\"]','[\"\\u0642\\u0633 \\u0636\\u063a\\u0637 \\u0627\\u0644\\u062f\\u0645\", \"\\u0627\\u0634\\u0631\\u0628 \\u0643\\u0645\\u064a\\u0629 \\u0643\\u0627\\u0641\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0627\\u0621\", \"\\u0627\\u0633\\u062a\\u0631\\u062d \\u0641\\u064a \\u0645\\u0643\\u0627\\u0646 \\u0647\\u0627\\u062f\\u0626 \\u0648\\u0645\\u0638\\u0644\\u0645\", \"\\u062a\\u062c\\u0646\\u0628 \\u0627\\u0644\\u0634\\u0627\\u06